{"file_path":"src/render.js","content":"export function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(cmp)
}

function scalarJson(n) {
  switch (n.t) {
    case 'integer': return String(n.v)
    case 'float': return JSON.stringify(n.v)
    case 'boolean': return n.v ? 'true' : 'false'
    default: return JSON.stringify(n.v)
  }
}

function emit(n, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + emit(n.map.get(k), indent + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + emit(v, indent + 1)).join(',\n') + '\n' + end + ']'
  }
  return scalarJson(n)
}

export function renderJson(root) {
  return emit(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : path + '.' + k
        const c = n.map.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

