{"file_path":"src/parse.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ t: 'table', map: new Map(), headerDefined: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isHex = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isAot = (n) => n.t === 'array' && n.aot

function fail(msg) {
  throw new ParseError(msg, 0)
}

// Descend through `segs` from `table`, creating tables on the way.
function walk(table, segs, base) {
  let cur = table
  for (let i = 0; i < segs.length; i++) {
    let child = cur.map.get(segs[i])
    if (child === undefined) {
      child = newTable()
      cur.map.set(segs[i], child)
    } else if (isAot(child)) {
      child = child.items[child.items.length - 1]
    } else if (child.t !== 'table') {
      fail(`${[...base, ...segs.slice(0, i + 1)].join('.')} is not a table`)
    }
    cur = child
  }
  return cur
}

function assign(table, segs, value, base) {
  const parent = walk(table, segs.slice(0, -1), base)
  const last = segs[segs.length - 1]
  if (parent.map.has(last)) fail(`key ${[...base, ...segs].join('.')} is defined twice`)
  parent.map.set(last, value)
}

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  peek() { return this.s[this.i] }
  skipWs() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }

  quoted() {
    const q = this.s[this.i++]
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (h.length !== 4 || ![...h].every(isHex)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail(`invalid escape \\${e}`)
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const segs = [this.name()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.s[this.i] === '.') {
        this.i++
        this.skipWs()
        segs.push(this.name())
      } else {
        this.i = save
        return segs
      }
    }
  }

  value(base) {
    if (this.atEnd() || ',]}'.includes(this.s[this.i])) fail('expected a value')
    const c = this.s[this.i]
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const run = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${run}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    const m = new RegExp(`^[+-]?${run}(?:\\.${run})?(?:[eE][+-]?${run})?$`)
    if (m.test(w) && /[.eE]/.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail(`invalid value ${w}`)
  }

  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.skipWs()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') { this.i++; break }
      items.push(this.value(base))
      this.skipWs()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') { this.i++; break }
      else fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }

  inline(base) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (this.s[this.i] === '}') { this.i++; return table }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) fail('unterminated inline table')
      const segs = this.dotted()
      this.skipWs()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.skipWs()
      const v = this.value([...base, ...segs])
      assign(table, segs, v, base)
      this.skipWs()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') { this.i++; return table }
      else fail('unterminated inline table')
    }
  }
}

function header(ln, root) {
  const dbl = ln.s[ln.i + 1] === '['
  ln.i += dbl ? 2 : 1
  ln.skipWs()
  const segs = ln.dotted()
  ln.skipWs()
  for (let k = 0; k < (dbl ? 2 : 1); k++) {
    if (ln.s[ln.i] !== ']') fail('unterminated table header')
    ln.i++
  }
  ln.skipWs()
  if (!ln.atEnd()) fail('trailing text after a table header')
  return { dbl, segs }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const ln = new Line(lines[n])
      ln.skipWs()
      if (ln.atEnd()) continue
      if (ln.peek() === '[') {
        const { dbl, segs } = header(ln, root)
        const parent = walk(root, segs.slice(0, -1), [])
        const last = segs[segs.length - 1]
        const path = segs.join('.')
        const ex = parent.map.get(last)
        if (dbl) {
          if (ex === undefined) {
            const fresh = newTable()
            parent.map.set(last, { t: 'array', items: [fresh], aot: true })
            current = fresh
          } else if (isAot(ex)) {
            const fresh = newTable()
            ex.items.push(fresh)
            current = fresh
          } else fail(`${path} is not an array of tables`)
        } else if (ex === undefined) {
          const t = newTable()
          t.headerDefined = true
          parent.map.set(last, t)
          current = t
        } else if (ex.t !== 'table') {
          fail(`${path} is not a table`)
        } else if (ex.headerDefined) {
          fail(`table ${path} is defined twice`)
        } else {
          ex.headerDefined = true
          current = ex
        }
        curPath = segs
        continue
      }
      const segs = ln.dotted()
      ln.skipWs()
      if (ln.s[ln.i] !== '=') fail('expected key = value')
      ln.i++
      ln.skipWs()
      const v = ln.value([...curPath, ...segs])
      ln.skipWs()
      if (!ln.atEnd()) fail('trailing text after a value')
      assign(current, segs, v, curPath)
    } catch (e) {
      if (e instanceof ParseError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

