        const parent = walk(root, segs.slice(0, -1), [])
        const last = segs[segs.length - 1]
        const path = segs.join('.')
        const ex = parent.map.get(last)
        if (dbl) {
          if (ex === undefined) {
            const fresh = newTable()
            parent.map.set(last, { t: 'array', items: [fresh], aot: true })
            current = fresh
          } else if (isAot(ex)) {
            const fresh = newTable()
            ex.items.push(fresh)
            current = fresh
          } else fail(`${path} is not an array of tables`)
        } else if (ex === undefined) {
          const t = newTable()
          t.headerDefined = true
          parent.map.set(last, t)
          current = t
        } else if (ex.t !== 'table') {
          fail(`${path} is not a table`)
        } else if (ex.headerDefined) {
          fail(`table ${path} is defined twice`)
        } else {
          ex.headerDefined = true
          current = ex
        }
        curPath = segs
        continue
      }
      const segs = ln.dotted()
      ln.skipWs()
      if (ln.s[ln.i] !== '=') fail('expected key = value')
      ln.i++
      ln.skipWs()
      const v = ln.value([...curPath, ...segs])
      ln.skipWs()
      if (!ln.atEnd()) fail('trailing text after a value')
      assign(current, segs, v, curPath)
    } catch (e) {
      if (e instanceof ParseError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

